delete from dp_lesson_blocks b using dp_lessons l, (values ('voice-evaluation-goals','teaching_section',1,'{"anchor": "teaching-focus", "section_number": "1", "heading": "Teaching focus: Vocal range assessment", "paragraphs": ["This session establishes where the voice is today. Hear the student sing a familiar song unaccompanied and then with a keyboard, note their comfortable lowest and highest pitches, where the sound feels easy or effortful, and how steady their pitch and breath are. Record it: this is the baseline for the final assessment.", "Ask what they want from coaching: congregational leading, solo work, recording, or confidence. Write two or three goals in the student''s own words and choose the first songs and keys from them.", "Draft for instructor adaptation: change the exercises, songs, keys and pacing to suit each student. Students do not have to follow an identical sequence."]}'),
 ('voice-evaluation-goals','takeaways',2,'{"items": [{"heading": "Key point 1", "body": "Range is mapped in comfort first; never push for extremes."}, {"heading": "Key point 2", "body": "Goals are specific enough to hear changing."}, {"heading": "Key point 3", "body": "The baseline recording is saved privately for comparison in the last session."}]}'),
 ('voice-breath-posture','teaching_section',1,'{"anchor": "teaching-focus", "section_number": "1", "heading": "Teaching focus: Breath coordination and posture", "paragraphs": ["Singing starts with an aligned, unforced stance: feet grounded, knees soft, spine long, shoulders and jaw released. Guide a quiet low inhale that lets the lower ribs and abdomen expand, then a steady, unvoiced exhale on a hiss or soft ''sh'' while keeping the chest from collapsing.", "Move from airflow to sound gradually: sustained hum, then a single vowel on one comfortable pitch. Watch for neck tension, raised shoulders and gripping the stomach. Stop and rest if the student feels light-headed.", "Draft for instructor adaptation: change the exercises, songs, keys and pacing to suit each student. Students do not have to follow an identical sequence."]}'),
 ('voice-breath-posture','takeaways',2,'{"items": [{"heading": "Key point 1", "body": "Posture first, then air, then sound."}, {"heading": "Key point 2", "body": "Steady airflow matters more than a big breath."}, {"heading": "Key point 3", "body": "Tension is information: pause and reset rather than push through."}]}'),
 ('voice-resonance-care','teaching_section',1,'{"anchor": "teaching-focus", "section_number": "1", "heading": "Teaching focus: Tone and resonance, stamina and healthy habits", "paragraphs": ["Teach a short repeatable warmup: gentle humming, lip trills and straw or ''ng'' glides in a comfortable range, then five-note patterns on open vowels. Explain tone as where the sound is allowed to ring: forward, relaxed and unforced, rather than squeezed in the throat.", "Healthy singing is also what happens outside lessons: hydration, rest, avoiding whispering and shouting when tired, and building stamina in short, regular practice rather than long strained sessions. Agree on when to lower the volume, take a break or stop.", "Draft for instructor adaptation: change the exercises, songs, keys and pacing to suit each student. Students do not have to follow an identical sequence."]}'),
 ('voice-resonance-care','takeaways',2,'{"items": [{"heading": "Key point 1", "body": "A warmup is consistent, gentle and the same every day."}, {"heading": "Key point 2", "body": "Resonance is freedom, not force."}, {"heading": "Key point 3", "body": "Short daily practice builds stamina; strain is a signal to stop."}]}'),
 ('voice-pitch-matching','teaching_section',1,'{"anchor": "teaching-focus", "section_number": "1", "heading": "Teaching focus: Pitch accuracy and ear training", "paragraphs": ["Train the ear before the voice. Play a note, ask the student to listen, imagine it, then sing it; compare to the piano and name whether they were under, over or on the pitch. Progress from single notes to two-note intervals, short patterns and then a phrase from a real song.", "Use recordings so the student can hear themselves honestly. Match in their comfortable range first, and use call-and-response and simple solfege or numbers to give them a way to think about pitch.", "Draft for instructor adaptation: change the exercises, songs, keys and pacing to suit each student. Students do not have to follow an identical sequence."]}'),
 ('voice-pitch-matching','takeaways',2,'{"items": [{"heading": "Key point 1", "body": "Listen, imagine, then sing."}, {"heading": "Key point 2", "body": "Hearing the difference is the skill that fixes pitch."}, {"heading": "Key point 3", "body": "Small, repeated wins in a comfortable range build accuracy."}]}'),
 ('voice-register-transitions','teaching_section',1,'{"anchor": "teaching-focus", "section_number": "1", "heading": "Teaching focus: Chest, head and mixed voice; vocal transitions", "paragraphs": ["Introduce the registers by feel: speech-like chest voice, lighter head voice and the blended mixed voice that connects them. Use sirens, hums and lip trills to move through the change without a crack or a push, and mark with the student where their transitions occur.", "Mixed voice develops slowly. Keep volume moderate, use vowels that help the blend, and choose songs whose melodies cross the transition gently. Update the range map from session one.", "Draft for instructor adaptation: change the exercises, songs, keys and pacing to suit each student. Students do not have to follow an identical sequence."]}'),
 ('voice-register-transitions','takeaways',2,'{"items": [{"heading": "Key point 1", "body": "Chest, head and mixed voice are one connected instrument."}, {"heading": "Key point 2", "body": "Smooth transitions come from balance, not volume."}, {"heading": "Key point 3", "body": "Map the student''s own transitions and select keys around them."}]}'),
 ('voice-agility-control','teaching_section',1,'{"anchor": "teaching-focus", "section_number": "1", "heading": "Teaching focus: Vocal agility", "paragraphs": ["Agility is accurate fast movement. Start slowly on three- and five-note patterns, then add scale fragments and simple turns, increasing the speed only while the pitch stays clean. Relaxed jaw and tongue and light airflow matter more than speed.", "Link it to repertoire: the runs and ornaments common in gospel and R&B. Break each ornament into slow pieces, record, and rebuild. Keep intonation honest by checking against the keyboard.", "Draft for instructor adaptation: change the exercises, songs, keys and pacing to suit each student. Students do not have to follow an identical sequence."]}'),
 ('voice-agility-control','takeaways',2,'{"items": [{"heading": "Key point 1", "body": "Slow and accurate first; speed is earned."}, {"heading": "Key point 2", "body": "Light airflow and a loose jaw keep runs clear."}, {"heading": "Key point 3", "body": "Practise ornaments in small pieces, then connect them."}]}'),
 ('voice-song-analysis','teaching_section',1,'{"anchor": "teaching-focus", "section_number": "1", "heading": "Teaching focus: Gospel, worship and R&B application", "paragraphs": ["Choose repertoire with the student that fits their range, current skill and goals, across gospel, worship or R&B as suits their ministry. Study the song as a whole: form, key, where the melody sits, breath points, entrances, phrase endings and the hardest notes.", "Decide on the key together and mark the score. If a song sits awkwardly, transpose it or choose a different one; the right key is a coaching decision, not a failure.", "Draft for instructor adaptation: change the exercises, songs, keys and pacing to suit each student. Students do not have to follow an identical sequence."]}'),
 ('voice-song-analysis','takeaways',2,'{"items": [{"heading": "Key point 1", "body": "The right song and key serve the voice."}, {"heading": "Key point 2", "body": "Know the map of the song before performing it."}, {"heading": "Key point 3", "body": "Mark breaths, entrances and difficult notes in advance."}]}'),
 ('voice-phrasing-dynamics','teaching_section',1,'{"anchor": "teaching-focus", "section_number": "1", "heading": "Teaching focus: Song interpretation", "paragraphs": ["Interpretation starts with meaning: what is the song saying, and to whom? Shape each phrase with a clear start, direction and landing, vary volume and intensity to serve the text, and let the vowel and consonant choices carry the message in gospel, worship and R&B styles.", "Have the student sing a verse twice, once plain and once with intentional choices, and compare recordings. Keep the expression honest and within the arrangement the director has set.", "Draft for instructor adaptation: change the exercises, songs, keys and pacing to suit each student. Students do not have to follow an identical sequence."]}'),
 ('voice-phrasing-dynamics','takeaways',2,'{"items": [{"heading": "Key point 1", "body": "Phrase with intention, not by habit."}, {"heading": "Key point 2", "body": "Dynamics and tone colour carry the meaning."}, {"heading": "Key point 3", "body": "Compare takes to hear what communicates."}]}'),
 ('voice-song-feedback','teaching_section',1,'{"anchor": "teaching-focus", "section_number": "1", "heading": "Teaching focus: Song interpretation and review", "paragraphs": ["Record a full section of the chosen song and review it together: pitch, breath, timing, tone and expression. Ask the student to name what they hear before giving your feedback, then choose one technical and one expressive improvement for the next week.", "The student then practises with the focus, records again and submits through the Hub so improvement is visible over attempts.", "Draft for instructor adaptation: change the exercises, songs, keys and pacing to suit each student. Students do not have to follow an identical sequence."]}'),
 ('voice-song-feedback','takeaways',2,'{"items": [{"heading": "Key point 1", "body": "Self-assessment first, coach feedback second."}, {"heading": "Key point 2", "body": "One technical and one expressive focus at a time."}, {"heading": "Key point 3", "body": "Recording each attempt makes growth audible."}]}'),
 ('voice-follow-direction','teaching_section',1,'{"anchor": "teaching-focus", "section_number": "1", "heading": "Teaching focus: Worship and ensemble application", "paragraphs": ["Leading a song means serving the whole team. Practise clear entrances, cue responses, tempo and key from the director or band, and singing within the arrangement''s structure without adding or removing sections unless directed.", "Rehearse with a track or accompanist, include a spoken transition and a cue to the next section, and discuss how to communicate with the band and sound team.", "Draft for instructor adaptation: change the exercises, songs, keys and pacing to suit each student. Students do not have to follow an identical sequence."]}'),
 ('voice-follow-direction','takeaways',2,'{"items": [{"heading": "Key point 1", "body": "Leadership is service within the arrangement."}, {"heading": "Key point 2", "body": "Clear cues and entrances build trust with the team."}, {"heading": "Key point 3", "body": "Prepare transitions as carefully as the song."}]}'),
 ('voice-confidence-engagement','teaching_section',1,'{"anchor": "teaching-focus", "section_number": "1", "heading": "Teaching focus: Performance confidence", "paragraphs": ["Confidence is built by preparation and repetition. Practise a short pre-performance routine of posture, breath and a settling thought, then perform a section as rehearsal and again as a simulated live lead, including eye contact, spoken words and recovery from a mistake.", "Help the student engage the room: invite participation, communicate the message of the song and keep their own voice healthy while doing so.", "Draft for instructor adaptation: change the exercises, songs, keys and pacing to suit each student. Students do not have to follow an identical sequence."]}'),
 ('voice-confidence-engagement','takeaways',2,'{"items": [{"heading": "Key point 1", "body": "A routine steadies nerves."}, {"heading": "Key point 2", "body": "Practise recovering from mistakes, not only avoiding them."}, {"heading": "Key point 3", "body": "Engagement is serving people through the song."}]}'),
 ('voice-final-evaluation','teaching_section',1,'{"anchor": "teaching-focus", "section_number": "1", "heading": "Teaching focus: Vocal development assessment", "paragraphs": ["Revisit the first-session song and record it again. Compare the two recordings with the student across pitch accuracy, range and transitions, tone, breath, agility, expression and confidence, and document specific changes and what remains to be developed.", "Together set the next goals: continued coaching, a specific ministry or audition, and a practice plan. Update the student''s progress record and decide on renewal.", "Draft for instructor adaptation: change the exercises, songs, keys and pacing to suit each student. Students do not have to follow an identical sequence."]}'),
 ('voice-final-evaluation','takeaways',2,'{"items": [{"heading": "Key point 1", "body": "Compare the first and last recordings side by side."}, {"heading": "Key point 2", "body": "Name concrete growth and the next focus areas."}, {"heading": "Key point 3", "body": "Leave with a practice plan and clear next goals."}]}')) v(slug,bt,oi,body) where l.id=b.lesson_id and l.slug=v.slug and b.block_type=v.bt and b.order_index=v.oi and b.content=v.body::jsonb;
